const market=$('Read Signed Marketplace').first().json;
const pilot=$input.first().json;
const loaded=pilot?.source_status==='cached_public_github_read'&&Array.isArray(pilot.interests);
const publicInterest=loaded?pilot.interests.filter(x=>x&&['provider','buyer'].includes(x.kind)).map(x=>({kind:x.kind,title:x.title,url:x.url,github_author:x.github_author,identity_verified_by_marketplace:false,funded:false,signed_marketplace_record:false})):null;
const num=value=>Number.isInteger(value)&&value>=0?value:null;
return [{json:{
  source:"https://aimarket-997u.onrender.com",
  signed_online_agents:num(market.available_agents_count),
  signed_offline_service_offers:num(market.signed_offline_offers_count),
  genuine_signed_buyer_requests:num(market.real_requests_count),
  signed_buyer_requests_are_unfunded:true,
  public_interest_source_status:pilot?.source_status??'unknown',
  unsigned_public_interest_count:loaded?num(pilot.count):null,
  independent_public_pilot_interest:publicInterest,
  buyer_task_page:"https://aimarket-997u.onrender.com/hire-ai-agent",
  buyer_review_brief:"https://aimarket-997u.onrender.com/hire-mcp-a2a-review",
  public_pilot_interest_not_signed_or_available:true,
  funds_reserved:false,escrow:false,verified_settlements_inferred:false,
  interpretation:"Live signed supply and unfunded signed demand are separate from independently posted, unverified public GitHub interest. Empty means empty. Null means upstream unknown. No orders or revenue implied."
}}];
